-- Forkville: tables for phpMyAdmin (generated by tools/build-sql.php). The prefix is fv_.

CREATE TABLE IF NOT EXISTS `fv_meta` (
    `k` VARCHAR(40) NOT NULL PRIMARY KEY,
    `v` VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_users` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(80) NOT NULL,
    `username` VARCHAR(20) NOT NULL,
    `email` VARCHAR(190) NOT NULL,
    `email_verified_at` DATETIME NULL,
    `password_hash` VARCHAR(255) NOT NULL DEFAULT '',
    `google_sub` VARCHAR(64) NULL,
    `role` TINYINT UNSIGNED NOT NULL DEFAULT 0,
    `status` ENUM('active','disabled') NOT NULL DEFAULT 'active',
    `created_at` DATETIME NOT NULL,
    `last_login_at` DATETIME NULL,
    UNIQUE KEY `uq_email` (`email`),
    UNIQUE KEY `uq_username` (`username`),
    UNIQUE KEY `uq_google` (`google_sub`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_auth_tokens` (
    `token_hash` CHAR(64) NOT NULL PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `csrf_token` CHAR(48) NOT NULL,
    `created_at` DATETIME NOT NULL,
    `last_seen_at` DATETIME NOT NULL,
    `expires_at` DATETIME NOT NULL,
    KEY `ix_user` (`user_id`),
    CONSTRAINT `fk_fv_tok_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_email_tokens` (
    `token_hash` CHAR(64) NOT NULL PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `created_at` DATETIME NOT NULL,
    `expires_at` DATETIME NOT NULL,
    KEY `ix_user` (`user_id`),
    CONSTRAINT `fk_fv_etok_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_attempts` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `kind` VARCHAR(20) NOT NULL,
    `ip` VARCHAR(45) NOT NULL,
    `created_at` DATETIME NOT NULL,
    KEY `ix_kind_ip` (`kind`, `ip`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_restaurants` (
    `user_id` INT UNSIGNED NOT NULL PRIMARY KEY,
    `name` VARCHAR(40) NOT NULL,
    `kind` VARCHAR(16) NOT NULL DEFAULT 'generic',
    `coins` BIGINT NOT NULL DEFAULT 0,
    `xp` INT UNSIGNED NOT NULL DEFAULT 0,
    `level` TINYINT UNSIGNED NOT NULL DEFAULT 1,
    `size` TINYINT UNSIGNED NOT NULL DEFAULT 10,
    `depth` TINYINT UNSIGNED NOT NULL DEFAULT 10,
    `parking` TINYINT UNSIGNED NOT NULL DEFAULT 0,
    `instance` VARCHAR(24) NULL,
    `floors` VARCHAR(200) NULL,
    `door` TINYINT UNSIGNED NULL,
    `door_style` VARCHAR(20) NOT NULL DEFAULT 'wood',
    `floor` VARCHAR(30) NOT NULL DEFAULT 'floor_oak',
    `wall` VARCHAR(30) NOT NULL DEFAULT 'wall_cream',
    `layout` MEDIUMTEXT NOT NULL,
    `staff` TEXT NOT NULL,
    `candidates` TEXT NULL,
    `menu` VARCHAR(400) NOT NULL DEFAULT '[]',
    `finishes` VARCHAR(600) NOT NULL DEFAULT '["floor_oak","wall_cream"]',
    `wish` VARCHAR(20) NULL,
    `status` ENUM('open','paused','closed') NOT NULL DEFAULT 'open',
    `paid_day` DATE NULL,
    `closed_from` DATETIME NULL,
    `closed_secs` INT UNSIGNED NOT NULL DEFAULT 0,
    `game_minutes` BIGINT UNSIGNED NOT NULL DEFAULT 540,
    `popularity` INT UNSIGNED NOT NULL DEFAULT 10,
    `rating_sum` INT UNSIGNED NOT NULL DEFAULT 0,
    `rating_n` INT UNSIGNED NOT NULL DEFAULT 0,
    `friend_sum` INT UNSIGNED NOT NULL DEFAULT 0,
    `friend_n` INT UNSIGNED NOT NULL DEFAULT 0,
    `served_total` INT UNSIGNED NOT NULL DEFAULT 0,
    `next_item_id` INT UNSIGNED NOT NULL DEFAULT 1,
    `last_report_at` DATETIME NOT NULL,
    `last_seen_at` DATETIME NOT NULL,
    `created_at` DATETIME NOT NULL,
    KEY `ix_popularity` (`popularity`),
    CONSTRAINT `fk_fv_rest_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_ingredients` (
    `user_id` INT UNSIGNED NOT NULL,
    `ing` VARCHAR(20) NOT NULL,
    `qty` INT UNSIGNED NOT NULL DEFAULT 0,
    PRIMARY KEY (`user_id`, `ing`),
    CONSTRAINT `fk_fv_ing_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_recipes` (
    `user_id` INT UNSIGNED NOT NULL,
    `dish` VARCHAR(30) NOT NULL,
    `level` TINYINT UNSIGNED NOT NULL DEFAULT 1,
    PRIMARY KEY (`user_id`, `dish`),
    CONSTRAINT `fk_fv_rec_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_garden` (
    `user_id` INT UNSIGNED NOT NULL,
    `plot` TINYINT UNSIGNED NOT NULL,
    `crop` VARCHAR(20) NOT NULL,
    `planted_at` DATETIME NOT NULL,
    `ready_at` DATETIME NOT NULL,
    PRIMARY KEY (`user_id`, `plot`),
    CONSTRAINT `fk_fv_gar_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_market_buys` (
    `user_id` INT UNSIGNED NOT NULL,
    `day` DATE NOT NULL,
    `ing` VARCHAR(20) NOT NULL,
    `qty` INT UNSIGNED NOT NULL DEFAULT 0,
    PRIMARY KEY (`user_id`, `day`, `ing`),
    CONSTRAINT `fk_fv_mkt_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_friends` (
    `user_id` INT UNSIGNED NOT NULL,
    `friend_id` INT UNSIGNED NOT NULL,
    `accepted` TINYINT(1) NOT NULL DEFAULT 0,
    `created_at` DATETIME NOT NULL,
    PRIMARY KEY (`user_id`, `friend_id`),
    KEY `ix_friend` (`friend_id`),
    CONSTRAINT `fk_fv_fr_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_fv_fr_friend` FOREIGN KEY (`friend_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_visits` (
    `user_id` INT UNSIGNED NOT NULL,
    `host_id` INT UNSIGNED NOT NULL,
    `day` DATE NOT NULL,
    `rating` TINYINT UNSIGNED NULL,
    `tip` INT UNSIGNED NOT NULL DEFAULT 0,
    PRIMARY KEY (`user_id`, `host_id`, `day`),
    KEY `ix_host` (`host_id`, `day`),
    CONSTRAINT `fk_fv_vis_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_fv_vis_host` FOREIGN KEY (`host_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_gifts` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `to_id` INT UNSIGNED NOT NULL,
    `day` DATE NOT NULL,
    `ing` VARCHAR(20) NOT NULL,
    `claimed_at` DATETIME NULL,
    `created_at` DATETIME NOT NULL,
    UNIQUE KEY `uq_day` (`user_id`, `to_id`, `day`),
    KEY `ix_to` (`to_id`, `claimed_at`),
    CONSTRAINT `fk_fv_gift_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_fv_gift_to` FOREIGN KEY (`to_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_reviews` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `stars` TINYINT UNSIGNED NOT NULL,
    `dish` VARCHAR(30) NOT NULL,
    `name` VARCHAR(20) NOT NULL,
    `good` VARCHAR(120) NOT NULL DEFAULT '',
    `bad` VARCHAR(120) NOT NULL DEFAULT '',
    `created_at` DATETIME NOT NULL,
    KEY `ix_user` (`user_id`, `id`),
    CONSTRAINT `fk_fv_rev_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_ledger` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `kind` VARCHAR(24) NOT NULL,
    `amount` INT NOT NULL,
    `detail` VARCHAR(120) NOT NULL DEFAULT '',
    `created_at` DATETIME NOT NULL,
    KEY `ix_user_time` (`user_id`, `created_at`),
    CONSTRAINT `fk_fv_led_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_settings` (
    `k` VARCHAR(40) NOT NULL PRIMARY KEY,
    `v` MEDIUMTEXT NOT NULL,
    `updated_at` DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_admin_log` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `admin_id` INT UNSIGNED NULL,
    `user_id` INT UNSIGNED NULL,
    `action` VARCHAR(40) NOT NULL,
    `detail` VARCHAR(500) NOT NULL DEFAULT '',
    `created_at` DATETIME NOT NULL,
    KEY `ix_user` (`user_id`, `created_at`),
    KEY `ix_time` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fv_weekly` (
    `user_id` INT UNSIGNED NOT NULL,
    `week` CHAR(8) NOT NULL,
    `coins` INT UNSIGNED NOT NULL DEFAULT 0,
    PRIMARY KEY (`user_id`, `week`),
    KEY `ix_week` (`week`, `coins`),
    CONSTRAINT `fk_fv_wk_user` FOREIGN KEY (`user_id`) REFERENCES `fv_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `fv_meta` (k, v) VALUES ('schema_version', '13') ON DUPLICATE KEY UPDATE v = VALUES(v);
